// Bütün olay ve hikâye kartları. Dünya düz JSON kalsın diye kart yalnızca {id,a} olarak saklanır.
import type {World,Person} from './types';
import {STAGES,DREAMS,MNAMES,FNAMES,TRADES,MATS} from './data';
import {addCrew,loseCrew,sellNow,soldFrac} from './project';
import {rnd,ri,pick,chance,clamp,year,pl,age,alive,full,money,log,sc,cash,rep,hurt,stress,hatir,bond,kids,spouse,addPerson,family,mon,ek} from './util';
export interface Opt{t:string;f?:(w:World,a:any)=>string|void;off?:boolean;hint?:string}
export interface Ev{id:string;kind?:'kotu'|'iyi'|'not';w?:number;gap?:number;c?:(w:World)=>boolean;mk?:(w:World)=>any;title:(w:World,a:any)=>string;text:(w:World,a:any)=>string;o:(w:World,a:any)=>Opt[];glass?:boolean;}
export const EV:Record<string,Ev>={};
const def=(e:Ev)=>{EV[e.id]=e;};
const hasF=(w:World)=>!!w.firm;const noF=(w:World)=>!w.firm;
const st=(w:World,n:number)=>!!w.firm&&w.firm.stage>=n;
const act=(w:World)=>w.projects.filter(p=>p.status==='insa');
const hasP=(w:World)=>act(w).length>0;
const anyP=(w:World,a?:any)=>w.projects.find(p=>p.id===a?.p)??act(w)[0];
const can=(w:World,n:number)=>w.cash>=n;
const flag=(w:World,k:string)=>!!w.flags[k];
const ok=(t:string,f?:Opt['f']):Opt=>({t,f});
const pay0=(t:string,k:number,f?:Opt['f']):Opt=>({t,f:(w,a)=>{const n=sc(w,k);if(w.cash<n){w.debt+=n-w.cash;w.cash=0;}else cash(w,-n);return f?f(w,a):undefined;}});
const pay=(w:World,n:number,t:string,f?:Opt['f']):Opt=>({t:t+' ('+money(n)+')',off:!can(w,n),f:(ww,a)=>{cash(ww,-n);return f?f(ww,a):undefined;}});
const later=(w:World,mo:number,id:string,a:any={})=>{w.sched.push({m:w.m+mo,id,a});};
const seal=(w:World,a:any,mo:number)=>{const p=anyP(w,a);if(p)p.seal=Math.max(p.seal,mo);};
export const LIVE_BLD=(w:World)=>w.buildings.filter(b=>b.state==='ayakta');

// ------------- İŞÇİLİK YILLARI -------------
def({id:'yevmiye_gec',kind:'kotu',c:noF,title:()=>'Yevmiye yine gecikti',text:(w)=>`${w.employer} iki haftadır "Cumaya" diyor. Koğuşta homurtu var, bakkal da veresiye defterini kapatmak üzere.`,o:(w)=>[
 ok('Sus, işini yap',(w)=>{stress(w,8);cash(w,-300);return'Para on gün sonra eksik geldi. Sesini çıkarmadın, ustalar not etti.';}),
 ok('Ustaları topla, şantiyeyi durdur',(w)=>{if(chance(w,.55)){cash(w,600);hatir(w,4);return'Parayı aldınız. Amelenin gözünde bir numaralısın artık.';}w.unemployed=2;return'Patron seni kapının önüne koydu. İki ay iş aradın.';}),
 ok('Bakkaldan hatır iste',(w)=>{hatir(w,-2);return'Bakkal deftere yazdı. "Unutmam," dedi, unutmadı da.';})]});
def({id:'sigorta',c:(w)=>noF(w)&&!flag(w,'sigorta'),title:()=>'Sigorta meselesi',text:()=>'Yeni kâtip önüne bir kâğıt koydu: "Sigortalı yaparız ama yevmiyen biraz düşer. Yapmazsak elden öderiz, fazla kalır."',o:()=>[
 ok('Sigortalı olayım',(w)=>{w.flags.sigorta=1;cash(w,-250);return'Yevmiyen düştü. Yıllar sonra bunun kıymetini anlayacaksın.';}),
 ok('Elden versin',(w)=>{w.flags.sigorta=-1;cash(w,500);return'Cebine fazladan para girdi. Bel fıtığı olan ustaların yüzüne bakmadın.';})]});
def({id:'kaza_isci',kind:'kotu',w:1.2,c:noF,title:()=>'İskeleden düştün',text:()=>'Sabah çiyinde tahta kaydı. İkinci kattan kum yığınının üstüne düştün. Bileğin şişiyor, ustabaşı "bir şey yok" diyor.',o:(w)=>[
 ok('Doktora git',(w)=>{const b=w.flags.sigorta===1?200:1200;cash(w,-b);hurt(w,6);w.unemployed=1;w.stats.accidents++;return w.flags.sigorta===1?'Sigorta masrafın çoğunu karşıladı. Bir ay dinlendin.':'Sigortan yoktu, parası cebinden çıktı. Bir ay çalışamadın.';}),
 ok('Sarıp işe devam et',(w)=>{hurt(w,14);w.stats.accidents++;w.xp+=2;return'Bilek iyileşti sandın. Soğukta sızlaması hiç geçmeyecek.';})]});
def({id:'isten_cikis',kind:'kotu',c:(w)=>noF(w)&&w.econ.phase==='kriz',title:()=>'Şantiye durdu',text:(w)=>`${w.employer} parayı bulamadı, bina karkasta kaldı. Herkese "şimdilik" dediler. Herkes "şimdilik"in ne demek olduğunu biliyor.`,o:()=>[
 ok('Başka şantiye ara',(w)=>{w.unemployed=ri(w,1,3);return'Kapı kapı dolaştın. Yevmiyesi düşük bir iş buldun.';}),
 ok('Köye dön, hasada yardım et',(w)=>{w.unemployed=2;bond(w,w.flags.anne,12);cash(w,300);return'Anan yüzünü gördü, sen de biraz nefes aldın.';}),
 ok('Ücret yerine malzeme iste',(w)=>{cash(w,800);hatir(w,-1);return'Yarım çuval çimento, biraz demir. Satınca bir aylık ettin.';})]});
def({id:'sulu_beton',c:noF,title:()=>'Mikserciye su',text:()=>'Beton kamyonu geldi, ustabaşı göz kırptı: "Biraz su kat da rahat aksın." Kolon, kaç yıl ayakta duracağını bilmeden bekliyor.',o:()=>[
 ok('Dediğini yap',(w)=>{w.guilt+=2;w.skills.beton+=1;return'Beton rahat aktı. Akşam yemeği boğazından geçmedi ama geçti.';}),
 ok('"Bu beton böyle dökülmez" de',(w)=>{w.skills.beton+=3;if(chance(w,.5)){hatir(w,3);return'Mühendis duydu, adını sordu.';}w.unemployed=1;return'Ustabaşı seni kapının önüne koydu. Haklıydın, işsizdin.';})]});
def({id:'cirak_bilgi',kind:'iyi',c:noF,title:()=>'Yaşlı kalıpçı',text:()=>'Öğle arasında yaşlı bir kalıpçı "gel bak" dedi. Yarım saatte, üç yılda öğreneceğin şeyi gösterdi. Karşılığında bir sigara istedi.',o:()=>[
 ok('Sigarayı ver, dinle',(w)=>{w.skills.kalip+=7;w.xp+=3;return'Elin alıştı. Gözün de.';})]});
def({id:'koy_mektup',c:noF,title:()=>'Köyden mektup',text:()=>'Anan yazdırmış: "Baban hasta, kardeşin okula gidecek, para lazım. Sen iyi misin oğlum, karnın doyuyor mu?"',o:(w)=>[
 pay(w,Math.min(2500,Math.max(300,Math.round(w.cash*.3))),'Para gönder',(w)=>{bond(w,w.flags.anne,15);return'Mektubun cevabında anan bir paket tarhana göndermiş.';}),
 ok('Bu ay gönderemem, yaz',(w)=>{bond(w,w.flags.anne,-8);stress(w,5);return'Yazarken kalem ağır geldi.';})]});
def({id:'kumar',kind:'kotu',c:(w)=>noF(w)&&w.cash>800,title:()=>'Koğuşta iskambil',text:()=>'Cuma akşamı koğuşta masa kuruldu. Karşındaki adam dün aylığını kazandı, "bir el otur" diyor.',o:(w)=>[
 ok('Otur',(w)=>{if(chance(w,.3)){cash(w,1200);return'Kazandın. En tehlikeli kumar da budur zaten.';}cash(w,-Math.round(w.cash*.5));stress(w,10);return'Paranın yarısı gitti. Sabah işe ayakların geri geri gitti.';}),
 ok('Kalk, yat',(w)=>{return'Sabah herkesin suratı asıktı, seninki değil.';})]});
def({id:'esnaf_hatir',kind:'iyi',c:noF,title:()=>'Bir duvar işi',text:()=>'Komşu bakkal arka duvarı çatlamış: "Pazar gelsen, hem hatırım olur hem harçlık veririm."',o:()=>[
 ok('Git, yap',(w)=>{cash(w,450);hatir(w,3);w.skills.duvar+=3;hurt(w,1);return'Duvar sağlam oldu. Bakkal üç kişiye adını söyledi.';}),
 ok('Pazar dinleneyim',(w)=>{w.health=clamp(w.health+2,1,100);return'Uyudun. O duvarı başkası ördü.';})]});
// ------------- AİLE -------------
def({id:'evlilik',c:(w)=>{const a=age(w,pl(w));return a>=20&&a<=42&&!spouse(w)&&!flag(w,'evlilikBekle');},w:3,gap:24,mk:(w)=>({list:[pick(w,pl(w).sex==='e'?FNAMES:MNAMES),pick(w,pl(w).sex==='e'?FNAMES:MNAMES),pick(w,pl(w).sex==='e'?FNAMES:MNAMES)],kin:['öğretmen, kitap okur, kirayı hesaplar','komşudan biri gibi, sıcakkanlı, sofrası geniş','hırslı bir ailenin çocuğu, çeyizi var, dili sivri']}),
 title:()=>'Görücü gibi, değil gibi',text:(w,a)=>`Mahallede konu açıldı, herkes bir isim söylüyor. ${a.list[0]}: ${a.kin[0]}. ${a.list[1]}: ${a.kin[1]}. ${a.list[2]}: ${a.kin[2]}.`,
 o:(w,a)=>{const wed=(i:number,tr:string,c:number,hit:string)=>ok(a.list[i]+' ile evlen',(w)=>{const me=pl(w);const s=addPerson(w,{name:a.list[i],sex:me.sex==='e'?'k':'e',by:me.by+ri(w,-48,24),sur:w.surname,trait:tr,bond:ri(w,60,85),dream:'',edu:i===0?40:10,gen:me.gen});w.flags['kan'+s.id]=0;s.sp=me.id;me.sp=s.id;cash(w,-Math.min(Math.max(0,w.cash*.3),sc(w,.4)));cash(w,c);log(w,`${s.name} ile evlendin.`,'aile');return hit;});
  return[wed(0,'durust',0,'Düğün küçük oldu. Evdeki defteri artık o tutuyor.'),wed(1,'sakin',0,'Sofra geniş, ev kalabalık. Gece eve dönmek istiyorsun artık.'),wed(2,'hirsli',sc(w,.3),'Çeyiz cebini rahatlattı. Hırsı seni de sürükleyecek.'),ok('Daha erken',(w)=>{w.flags.evlilikBekle=1;later(w,ri(w,18,36),'_unflag',{k:'evlilikBekle'});return'Ananın yüzü asıldı.';})];}});
def({id:'_unflag',title:()=>'',text:()=>'',o:()=>[]});
def({id:'cocuk_okul',c:(w)=>kids(w).some(k=>age(w,k)>=14&&age(w,k)<=18&&!flag(w,'okul'+k.id)),w:2,mk:(w)=>({k:kids(w).find(k=>age(w,k)>=14&&age(w,k)<=18&&!flag(w,'okul'+k.id))!.id}),title:(w,a)=>w.people[a.k].name+' ne olacak?',text:(w,a)=>{const k=w.people[a.k];return `${k.name} ${age(w,k)} yaşında. Hayali ${DREAMS[k.dream]||'belli değil'}. Yeteneği ${k.tal>65?'göze çarpıyor':k.tal>40?'fena değil':'şantiyede pek işe yaramaz'}.`;},o:(w,a)=>{const k=w.people[a.k];const c=Math.max(2000,sc(w,.4));return[
 pay(w,c,'Hayalinin peşinden gitsin, okut',(w)=>{const k=w.people[a.k];w.flags['okul'+k.id]=1;k.edu+=40;bond(w,k.id,18);return`${k.name} sana sarıldı. Büyüyünce şantiyeye dönmeyebilir.`;}),
 ok('Şantiyeye gelsin, işi öğrensin',(w)=>{const k=w.people[a.k];w.flags['okul'+k.id]=1;k.work+=20;if(k.dream!=='insaat')bond(w,k.id,-18);return`${k.name} sabah sessizce kamyonete bindi.`;}),
 pay(w,c*2,'Mimarlık ya da mühendislik okusun',(w)=>{const k=w.people[a.k];w.flags['okul'+k.id]=1;k.edu+=60;k.work+=10;if(k.dream==='insaat'||k.dream==='mimar')bond(w,k.id,15);else bond(w,k.id,-6);return`${k.name} şehir dışına gitti. Dönerse şirketin yeni dili o olur.`;})];}});
def({id:'cocuk_hasta',kind:'kotu',c:(w)=>kids(w).length>0,title:()=>'Hastane koridoru',text:(w,a)=>`${w.people[a.k].name} ateşler içinde. Doktor "özel bir tedavi lazım" dedi. Şantiyede de yarın beton var.`,mk:(w)=>({k:pick(w,kids(w)).id}),o:(w,a)=>[
 pay(w,sc(w,.5),'Özel hastaneye yatır, başından ayrılma',(w)=>{bond(w,a.k,12);seal(w,{},1);return'Çocuk iyileşti. Beton sen yokken döküldü, sonucu bilinmez.';}),
 ok('Devlet hastanesi, karın baksın',(w)=>{bond(w,a.k,-6);bond(w,w.people[w.playerId].sp,-8);return'İyileşti. "Babam gelmedi" dediğini sonra duydun.';})]});
def({id:'mezuniyet',c:(w)=>kids(w).length>0&&hasP(w),title:(w,a)=>ek(w.people[a.k].name,'gen')+' mezuniyeti',text:()=>'Aynı saatte belediyede ruhsat görüşmesi var. İkisi de ertelenmiyor.',mk:(w)=>({k:pick(w,kids(w)).id}),o:(w,a)=>[
 ok('Mezuniyete git',(w)=>{bond(w,a.k,18);seal(w,{},2);rep(w,-1);return'En arka sırada alkışladın. Ruhsat iki ay gecikti.';}),
 ok('Belediyeye git',(w)=>{bond(w,a.k,-16);hatir(w,3);return'Ruhsat çıktı. Fotoğrafta sen yoksun.';})]});
def({id:'es_kavga',kind:'kotu',c:(w)=>!!spouse(w)&&w.evening!=='aile'&&spouse(w)!.bond<45,title:()=>'Mutfakta gece yarısı',text:(w)=>`${spouse(w)!.name} kapının önünde bekliyor: "Bu evde hayalet gibi dolaşıyorsun. Çocuklar seni şantiye önünden tanıyor."`,o:(w)=>[
 pay(w,sc(w,.2),'Bir hafta her şeyi bırak, tatile çık',(w)=>{bond(w,w.people[w.playerId].sp,22);stress(w,-12);return'Deniz kenarında ilk kez telefonu kapattın.';}),
 ok('"Bu ev o şantiye sayesinde dönüyor" de',(w)=>{bond(w,w.people[w.playerId].sp,-15);stress(w,6);return'Kapı çarptı. Kanepede uyudun.';})]});
def({id:'bosanma',kind:'kotu',w:2,c:(w)=>!!spouse(w)&&spouse(w)!.bond<20,title:()=>'Boşanma evrakı',text:(w)=>`Avukat zarfı masaya bıraktı. ${spouse(w)!.name} evin ve şirketin yarısında hakkı olduğunu yazmış.`,o:(w)=>[
 pay(w,Math.max(0,Math.round(Math.max(w.cash,0)*.35)),'Anlaş, payını ver',(w)=>{const s=spouse(w)!;s.sp=undefined;pl(w).sp=undefined;stress(w,10);log(w,`${s.name} ile boşandın.`,'aile');return'Sessiz bitti. Çocuklar iki ev arasında büyüyecek.';}),
 pay(w,sc(w,.3),'Gidip affını iste',(w)=>{const s=spouse(w)!;if(chance(w,.55)){bond(w,s.id,35);return'Zarfı yırttı. Bu sefer son sefer.';}cash(w,-Math.round(Math.max(0,w.cash)*.4));s.sp=undefined;pl(w).sp=undefined;log(w,`${s.name} ile boşandın.`,'aile');return'Olmadı. Mahkeme onun lehine bitti.';})]});
def({id:'akraba_hirsiz',kind:'kotu',c:(w)=>hasF(w)&&family(w).some(p=>p.work>10),title:()=>'Kasada eksik para',text:(w,a)=>`Muhasebeci sessizce defteri uzattı: ${w.people[a.k].name} aylardır kasadan alıp yazmıyor. Kumar mı, kadın mı, başka bir şey mi, bilinmez.`,mk:(w)=>({k:pick(w,family(w).filter(p=>p.work>10)).id}),o:(w,a)=>[
 ok('Örtbas et, parayı kendin kapat',(w)=>{cash(w,-sc(w,.6));bond(w,a.k,10);return'Aile içinde kaldı. Defteri de sen tutmaya başladın.';}),
 ok('Herkesin önünde hesap sor',(w)=>{bond(w,a.k,-40);cash(w,-sc(w,.2));return'Yemekte kimse konuşmadı. Bir yıl kapını çalmadı.';}),
 ok('Şirketten çıkar, savcıya gitme',(w)=>{const k=w.people[a.k];k.work=0;bond(w,a.k,-22);return k.name+' gitti. Kasadaki delik kapandı.';})]});
def({id:'yegen_is',kind:'iyi',c:(w)=>hasF(w)&&family(w).some(p=>age(w,p)>=18&&age(w,p)<35&&p.work<10&&p.id!==pl(w).sp),title:(w,a)=>w.people[a.k].name+' iş istiyor',text:(w,a)=>{const k=w.people[a.k];return`${k.name} (${age(w,k)}) kapıda: "Beni de al, sıfırdan başlarım." Yeteneği ${k.tal>60?'iyi görünüyor':'şüpheli'}, huyu ${k.trait==='savurgan'?'savurgan':'düzgün'}.`;},mk:(w)=>({k:pick(w,family(w).filter(p=>age(w,p)>=18&&age(w,p)<35&&p.work<10&&p.id!==pl(w).sp)).id}),o:(w,a)=>[
 ok('Şantiyeye al',(w)=>{const k=w.people[a.k];k.work+=15;bond(w,k.id,12);return k.name+' baret taktı. Varis listende bir isim daha var.';}),
 ok('Aile işe karışmasın',(w)=>{bond(w,a.k,-14);return'Kırgın gitti, rakibin kapısını çaldığı söyleniyor.';})]});
def({id:'es_bilezik',kind:'iyi',w:.6,c:(w)=>!!spouse(w)&&hasF(w)&&w.cash<sc(w,1.2)&&!flag(w,'bilezik'),title:()=>'Bilezikler',text:(w)=>`Arsa parası eksik, banka kapıyı kapattı. ${spouse(w)!.name} akşam mutfak masasına altı bileziğini koydu: "Al. Satarsın. Batarsak bilezik mi kalır?"`,o:(w)=>[
 ok('Al, sonra iki katını alacaksın',(w)=>{w.flags.bilezik=w.m;cash(w,sc(w,1.2));bond(w,w.people[w.playerId].sp,14);later(w,ri(w,48,96),'bilezik_don');return'Kuyumcunun önünden hızlı geçtin.';}),
 ok('Geri koy, başka yol bulacağım',(w)=>{bond(w,w.people[w.playerId].sp,6);stress(w,5);return'Bilezikler koluna döndü, yükü senin omzuna.';})]});
def({id:'bilezik_don',title:()=>'Sözün vardı',text:(w)=>spouse(w)?`${spouse(w)!.name} artık hiç bahsetmiyor. Ama pazarda vitrin önünde bir an durdu.`:'Bilezikleri aldığın kişi artık yok. Kuyumcunun önünden yine hızlı geçtin.',o:(w)=>spouse(w)?[pay(w,sc(w,.8),'Altı bilezik al, üstüne bir tane daha',(w)=>{bond(w,w.people[w.playerId].sp,35);return'Ağladı. Sen de.';}),ok('Bu yıl olmaz',(w)=>{bond(w,w.people[w.playerId].sp,-20);return'Sormadı bile. Asıl kötü olan oydu.';})]:[ok('Geçti artık',(w)=>{stress(w,6);return'Bazı borçlar ödenmez.';})]});
def({id:'kardes_borc',c:(w)=>family(w).some(p=>p.gen===pl(w).gen&&p.id!==pl(w).sp)&&w.cash>sc(w,.5),mk:(w)=>({k:pick(w,family(w).filter(p=>p.gen===pl(w).gen&&p.id!==pl(w).sp)).id}),title:(w,a)=>w.people[a.k].name+' kapıda',text:(w,a)=>`${w.people[a.k].name} ilk kez yüzüne bakmadan konuşuyor: borcu var, çocuğun okulu var, utanıyor.`,o:(w,a)=>[
 pay(w,sc(w,.4),'Ver, geri isteme',(w)=>{bond(w,a.k,22);hatir(w,2);return'Kapıda sarıldı. Bir daha bu konuyu açmadınız.';}),
 ok('"Çalışsın" de',(w)=>{bond(w,a.k,-22);return'Bayramda ilk kez aramadı.';})]});
def({id:'bayram',kind:'iyi',w:1.2,gap:18,c:(w)=>family(w).length>1,title:()=>'Bayram sofrası',text:()=>'Herkes bir aradaysa ev dar gelir. Çocuklar el öpmek için sıraya girdi, biri bu yıl şirketi soruyor.',o:(w)=>[
 pay(w,sc(w,.15),'Herkesi topla, harçlıkları büyük ver',(w)=>{for(const p of family(w))bond(w,p.id,5);stress(w,-6);return'Bir akşam için herkes herkesle konuştu.';}),
 ok('Küçük tut',(w)=>{return'Çay içildi, dağılındı.';})]});
// ------------- ŞANTİYE -------------
def({id:'is_kazasi',kind:'kotu',w:1.8,gap:30,c:hasP,title:()=>'İş kazası',text:(w,a)=>`${a.who}, ${a.p} şantiyesinde iskeleden düştü. Ambulans geldi. Müfettiş de yolda. Tüm ustalar sana bakıyor.`,mk:(w)=>({who:pick(w,MNAMES)+' Usta',p:act(w)[0].name}),o:(w,a)=>[
 pay(w,sc(w,.7),'Ailesini sen karşıla, güvenliği düzelt',(w)=>{rep(w,1);w.firm!.qual=clamp(w.firm!.qual+2,0,100);w.stats.accidents++;seal(w,{},1);return'Şantiye bir ay durdu. Ustalar bu ayı unutmayacak.';}),
 ok('Sigortasıymış gibi göster',(w)=>{w.stats.accidents++;w.guilt+=4;cash(w,-sc(w,.15));if(chance(w,.35)){cash(w,-sc(w,.8));rep(w,-8);seal(w,{},4);return'Tutmadı. Dava ve mühür geldi, gazeteler adını yazdı.';}return'Geçti. Adamın karısı bir daha selam vermedi.';}),
 ok('Avukata bırak',(w)=>{w.stats.accidents++;cash(w,-sc(w,.3));rep(w,-3);seal(w,{},2);return'Dava yıllarca sürecek gibi. Ustalar sessiz.';})]});
def({id:'muhur',kind:'kotu',w:1.2,c:hasP,title:()=>'Şantiye mühürlendi',text:(w)=>`Belediye ekipleri ${act(w)[0].name} kapısına kırmızı bant çekti. Tutanakta iki eksik, bir de kimin şikâyet ettiği belirsiz.`,o:(w)=>[
 pay(w,sc(w,.3),'Eksikleri gider, cezayı öde',(w)=>{seal(w,{},2);return'İki ay yitti, kalem sağlam kaldı.';}),
 ok('Tanıdıkla çöz',(w)=>{if(w.hatir>=8){hatir(w,-8);return'Bir telefonla kalktı. Şimdi o tanıdığa borçlusun.';}seal(w,{},4);rep(w,-3);return'Tanıdık o kadar da tanıdık değilmiş. Dört ay durdun.';}),
 pay(w,sc(w,.2),'Zarf ver',(w)=>{w.guilt+=2;if(chance(w,.25)){w.flags.rusvetDos=1;seal(w,{},3);rep(w,-5);return'Tam da o gün kamera varmış. Dosya savcıya gitti.';}return'Bant akşam kalktı. Adam bir daha uğrayacak.';})]});
def({id:'taseron_kacti',kind:'kotu',w:1.2,c:(w)=>hasP(w)&&st(w,2),title:()=>'Taşeron kaçtı',text:(w)=>`Kaba inşaat taşeronu avansı aldı, sabah telefonu kapalı. ${act(w)[0].name} işçileri yevmiye bekliyor.`,o:(w)=>[
 pay(w,sc(w,.5),'İşçilerin parasını öde, ekibi tut',(w)=>{w.firm!.qual=clamp(w.firm!.qual+3,0,100);rep(w,2);return'Zararı yuttun. Bu hikâye hatırını artırdı.';}),
 ok('"Taşeronun işi" de',(w)=>{rep(w,-5);loseCrew(w,.15);const p=act(w)[0];if(p)p.prog=Math.max(0,p.prog-.04);return'Usta takımı dağıldı, iş geriye gitti.';})]});
def({id:'zemin',kind:'kotu',c:(w)=>act(w).some(p=>p.prog<.25),mk:(w)=>({p:act(w).find(p=>p.prog<.25)!.id}),title:()=>'Kazıdan su çıktı',text:(w,a)=>`${anyP(w,a).name} temelinde kepçe suya vurdu. Zemin raporu "sağlam" diyordu. Rapor pek de zemine bakılarak yazılmamış.`,o:(w,a)=>[
 pay(w,sc(w,.7),'Fore kazık çak, drenaj yap',(w)=>{const p=anyP(w,a);p.struct+=8;return'Pahalıya patladı. Bina artık kayaya basıyor.';}),
 ok('Biraz doldur, devam et',(w)=>{const p=anyP(w,a);p.struct-=18;w.guilt+=5;return'Kimse görmedi. Yağmurlu gecelerde aklına gelecek.';})]});
def({id:'tarihi',kind:'kotu',w:.9,c:(w)=>act(w).some(p=>p.prog<.3&&STAGES[p.stage].kind==='sat'),mk:(w)=>({p:act(w).find(p=>p.prog<.3)!.id}),title:()=>'Kepçe bir şeye çarptı',text:()=>'Kazıda taş bir sütun başı çıktı. Operatör kepçeyi durdurup sana bakıyor. Bir yanda müze ve belirsiz bir bekleyiş, bir yanda hemen üstüne dökülecek bir beton.',o:(w,a)=>[
 ok('Müzeye haber ver',(w)=>{seal(w,a,ri(w,5,10));rep(w,5);hatir(w,4);return'Şantiye aylarca durdu. Gazete sana "örnek müteahhit" dedi, banka faizi saydı.';}),
 ok('Üstüne dök',(w)=>{w.guilt+=7;w.flags.eser=(w.flags.eser||0)+1;if(chance(w,.25))later(w,ri(w,24,80),'eser_ifsa');return'Sabaha iş kalmadı. Operatöre bir maaş ikramiye verdin.';}),
 pay(w,sc(w,.2),'Gizlice çıkar, koleksiyoncuya sat',(w)=>{w.guilt+=5;cash(w,sc(w,1.2));later(w,ri(w,36,120),'eser_ifsa');return'Para iyi. Adam da çok konuşkan görünüyor.';})]});
def({id:'eser_ifsa',kind:'kotu',title:()=>'Operatör konuştu',text:()=>'Yıllar sonra eski kepçe operatörü bir gazeteciye her şeyi anlattı. Savcılık bir yazı gönderdi.',o:(w)=>[
 pay(w,sc(w,1),'Avukat tut, sonuna kadar diren',(w)=>{rep(w,-6);return'Dava düştü, ama adın gazeteden silinmedi.';}),
 ok('Kabul et, cezayı öde',(w)=>{cash(w,-sc(w,1.5));rep(w,-3);w.guilt=Math.max(0,w.guilt-5);return'İtiraf içini biraz hafifletti, kasayı değil.';})]});
def({id:'sahte_demir',kind:'kotu',c:hasP,title:()=>'Demirciden ucuz fırsat',text:()=>'Tüccar göz kırptı: "Aynı demir, faturası başka. %20 ucuz." Nakit sıkışık, kimse anlamaz.',o:(w)=>[
 ok('Al',(w)=>{const p=act(w)[0];cash(w,sc(w,.25));p.struct-=10;p.defects.push({trade:'demir',sev:10,txt:'Faturasız, standart dışı demir kullanılmış',found:false});w.guilt+=4;return'Kasa nefes aldı. Demir kolona girdi.';}),
 ok('Geri çevir',(w)=>{rep(w,1);return'Tüccar omuz silkti. Başka müteahhide gitti, onu da duyacaksın.';})]});
def({id:'komsu',c:hasP,title:()=>'Komşu şikâyeti',text:()=>'Yan apartmanın üçüncü katındaki teyze camdan bağırıyor: duvarı çatlamış, çamaşırı toz olmuş, torunu uyuyamıyor.',o:(w)=>[
 pay(w,sc(w,.1),'Duvarını onar, çay iç',(w)=>{rep(w,2);hatir(w,2);return'Şikâyetçi teyze mahallenin en iyi emlakçısına dönüştü.';}),
 ok('Yok say',(w)=>{if(chance(w,.4)){seal(w,{},1);rep(w,-2);return'Teyze zabıtayı çağırdı. Bir hafta değil, bir ay.';}return'Bağırdı, sustu.';})]});
def({id:'grev',kind:'kotu',c:(w)=>st(w,6)&&hasP(w),title:()=>'Şantiyede iş bırakma',text:()=>'Yevmiye iki ay gecikti diye usta takımı kollarını bağladı. Başlarında genç bir ustabaşı. Yüzü sana tanıdık geliyor; eskiden sen de öyle bakardın.',o:(w)=>[
 pay(w,sc(w,.5),'Birikmiş parayı öde, oturup konuş',(w)=>{w.firm!.qual=clamp(w.firm!.qual+4,0,100);return'İş başladı. Ustabaşını yanına aldın.';}),
 ok('Hepsini çıkar, yeni ekip al',(w)=>{w.firm!.qual=clamp(w.firm!.qual-15,0,100);rep(w,-4);w.guilt+=3;const p=act(w)[0];if(p)p.prog=Math.max(0,p.prog-.03);return'Yeni gelenler işi bilmiyor. Kolonlar da biliyor bunu.';})]});
def({id:'yangin',kind:'kotu',w:.6,c:(w)=>w.projects.length>0&&st(w,4),title:()=>'Şantiyede yangın',text:()=>'Gece bekçisinin sobası devrildi. Malzeme deposu yandı, sigorta poliçesinin süresi geçen ay dolmuş.',o:(w)=>[ok('Zararı kapat',(w)=>{cash(w,-sc(w,.9));return'Sabah küle baktın. Sonra çay içtin. Sonra hesap yaptın.';}),ok('Bekçiyi suçla, hepsini ondan iste',(w)=>{cash(w,-sc(w,.75));w.guilt+=3;rep(w,-3);return'Yaşlı adamdan hiçbir şey alınmadı, sadece adın kötüye çıktı.';})]});
def({id:'malzeme',kind:'kotu',c:hasP,title:()=>'Malzeme gelmedi',text:()=>'Depocu hesabı kesti: "Eski borcu kapatmadan çimento yok." Beton günü yarın, mikser saati alınmış.',o:(w)=>[pay(w,sc(w,.3),'Hemen kapat',()=>'Mikser zamanında geldi.'),ok('Hatrınla çöz',(w)=>{if(w.hatir>2){hatir(w,-3);return'Depocu baban gibi: "Hadi bakalım, bu son."';}seal(w,{},1);return'Hatır bakiyen boş. Bir ay kaybettin.';})]});
def({id:'ceza_vergi',kind:'kotu',w:1.3,c:hasF,title:()=>'Vergi incelemesi',text:(w)=>`Müfettiş ofise geldi. Masada iki deftere bakıyor, hangisi gerçek diye sormadı ama soracak.${w.car>=4?' Aşağıdaki arabana da baktı.':''}`,o:(w)=>[
 pay(w,sc(w,.8),'Uzlaş, öde',()=>'Masa temizlendi. Bu yıl kâr dediğin şey buraya gitti.'),
 ok('Muhasebeciyle çarpış',(w)=>{if(chance(w,.45)){return'Evrakı sağlam çıktı. Muhasebeciye bir maaş ikramiye.';}cash(w,-sc(w,1.5));rep(w,-4);return'Yakalandın. Ceza üç katı.';})]});
def({id:'davasi',kind:'kotu',w:1.2,c:(w)=>w.buildings.length>2,mk:(w)=>({b:pick(w,w.buildings).name}),title:()=>'Daire sahibi dava açtı',text:(w,a)=>`${a.b} sakinleri: kaçak su, çatlak balkon, eksik iskân. Mahkeme bilirkişi atadı.`,o:(w)=>[
 pay(w,sc(w,.4),'Onar, uzlaş',(w)=>{rep(w,2);return'Onarım ekibi gitti, sakinler kek yaptı.';}),
 ok('Mahkemeye bırak',(w)=>{if(chance(w,.5)){cash(w,-sc(w,.2));return'Yıllarca sürdü, az ödedin.';}cash(w,-sc(w,.8));rep(w,-5);return'Kaybettin, gazeteye de çıktı.';})]});
def({id:'hapis',kind:'kotu',w:.5,gap:200,c:(w)=>hasF(w)&&(flag(w,'rusvetDos')||w.guilt>30),title:()=>'Soruşturma',text:()=>'Sabah altıda kapı çalındı. Eski bir dosya açılmış: ruhsat, zarf, tanıklar. Avukatın "bir süre içeride kalabilirsin" diyor.',o:(w)=>[
 pay(w,sc(w,2),'Her şeyi dene, en iyi avukat',(w)=>{if(chance(w,.6)){rep(w,-8);w.flags.rusvetDos=0;return'Kurtuldun. Fiyatı pahalı, ün yaralı.';}w.jail=ri(w,8,18);rep(w,-12);w.stats.jail++;return'Olmadı. İçeri girdin; şirketi dışarıdakiler yönetiyor.';}),
 ok('Teslim ol, cezanı çek',(w)=>{w.jail=ri(w,6,14);w.guilt=Math.max(0,w.guilt-15);w.flags.rusvetDos=0;rep(w,-10);w.stats.jail++;log(w,'Hapse girdin.','kotu');return'Kapı kapandı. İlk kez gece deliksiz uyudun.';})]});
def({id:'belge_iptal',kind:'kotu',w:.8,gap:180,c:(w)=>hasF(w)&&w.firm!.cert>1&&(w.guilt>12||w.firm!.rep<25),title:()=>'Belgen düşürüldü',text:(w)=>`Bakanlık yazısı: yeterlik koşulları kaybedilmiş sayılıyor. ${w.firm!.cert>0?'Grubun bir basamak iniyor.':''}`,o:(w)=>[ok('Kabul et, yeniden başvur',(w)=>{w.firm!.cert=Math.max(0,w.firm!.cert-1);rep(w,-5);return'Tabelada harf değişti, herkes gördü.';}),pay(w,sc(w,.7),'Mahkemede yürütmeyi durdur',(w)=>{if(chance(w,.5))return'Karar lehine çıktı. Şimdilik.';w.firm!.cert=Math.max(0,w.firm!.cert-1);return'Olmadı. Para da gitti.';})]});
def({id:'kriz_satis',kind:'kotu',c:(w)=>w.econ.phase==='kriz'&&w.projects.some(p=>p.status==='satis'),title:()=>'Daireler satılmıyor',text:()=>'Satış ofisine bu ay iki kişi geldi, ikisi de "bakıyorduk" dedi. Banka her sabah arıyor.',o:(w)=>[
 ok('%20 indir, nakit gelsin',(w)=>{const p=w.projects.find(p=>p.status==='satis')!;sellNow(w,p,.3,.8);return'Daireler gitti, kâr da gitti.';}),
 ok('Bekle, fiyatı bozma',(w)=>{stress(w,8);return'Sabır ucuz değil. Faiz işliyor.';}),
 ok('Daireyi ustalara yevmiye yerine ver',(w)=>{const p=w.projects.find(p=>p.status==='satis')!;sellNow(w,p,.1,.75);w.firm!.qual=clamp(w.firm!.qual+2,0,100);return'Usta da daire sahibi oldu, sen de nefes aldın.';})]});
def({id:'fiyat_sok',kind:'kotu',c:(w)=>w.econ.fx>1.2&&hasP(w),title:()=>'Maketten sattığın daireler',text:()=>'Dolar sıçradı, demir bir ayda %30 arttı. Geçen yıl ucuza sattığın dairelerin sahipleri, "söz verdin" diye önündeler.',o:(w)=>[
 pay(w,sc(w,.7),'Sözünü tut, zararını yut',(w)=>{rep(w,5);return'Mahalleden "bu adam sözünün eri" sesi çıktı.';}),
 ok('Sözleşmeye ek iste',(w)=>{rep(w,-6);return'Kimi kabul etti, kimi dava açtı.';})]});
def({id:'denetci',kind:'kotu',c:(w)=>hasP(w)&&year(w)>=2001,title:()=>'Yapı denetçisi',text:()=>'Denetçi kolon demirine bakıp kalemini bıraktı. "İmzalayamam," dedi, "ama isterseniz konuşuruz."',o:(w)=>[
 pay(w,sc(w,.3),'Eksikleri söktür, yeniden yaptır',(w)=>{const p=act(w)[0];p.struct+=5;for(const d of p.defects)d.found=true;return'Hakkını teslim etti. Bu adamı bir yere yaz.';}),
 pay(w,sc(w,.15),'Konuşalım',(w)=>{w.guilt+=5;const p=act(w)[0];p.struct-=6;p.bribe=true;return'İmza atıldı. Elin titredi mi? Hayır. Sorun da bu.';})]});
// ------------- İYİ OLAYLAR / FIRSATLAR -------------
def({id:'imar',kind:'iyi',c:(w)=>(w.inv.tarla||0)>0,title:()=>'İmar geldi',text:()=>'Yıllardır ot biten tarlaya imar planı gelmiş. Emlakçı aramaya başladı, belediyeden biri de "önceden biliyor muydun?" diye sordu.',o:(w)=>[ok('Sevin, sat',(w)=>{const g=w.inv.tarla*2.5;cash(w,g);w.inv.tarla=0;return`${money(g)} geçti eline.`;}),ok('Satma, bekle',(w)=>{w.inv.tarla*=2.1;return'Değer tapuda duruyor.';})]});
def({id:'veresiye',kind:'iyi',c:(w)=>hasF(w)&&w.hatir>=10&&w.cash<sc(w,.5),title:()=>'Hatır defteri',text:()=>'Yıllar önce yardım ettiğin nalbur ustası aradı: "Duydum sıkıştığını. Malzemeyi al, parayı unut, sonra konuşuruz."',o:(w)=>[ok('Minnetle kabul et',(w)=>{cash(w,sc(w,.8));hatir(w,-8);return'Bu dünyada asıl sermaye bu.';})]});
def({id:'buyuk_alici',kind:'iyi',c:(w)=>w.projects.some(p=>p.status==='satis'&&p.sold<.7),title:()=>'Toplu alıcı',text:()=>'Gurbetten dönen bir aile "kaç daire kaldı?" diye sordu. Hepsini peşin alabilirler, küçük bir indirimle.',o:(w)=>[ok('Sat',(w)=>{const p=w.projects.find(p=>p.status==='satis')!;sellNow(w,p,1,.88);return'Satış bir öğleden sonrada bitti.';}),ok('Fiyat kırmam',()=>'Çay içtiler, gittiler.')]});
def({id:'gazete',kind:'iyi',c:(w)=>w.buildings.length>2&&w.guilt<8,title:()=>'Gazetede adın',text:(w)=>`Yerel gazete manşet attı: "${w.surname} binaları: şikâyetsiz yirmi yıl." Telefon çalmaya başladı.`,o:(w)=>[ok('Çerçevele, ofise as',(w)=>{rep(w,6);return'Baban görse ne derdi?';})]});
def({id:'iyi_usta',kind:'iyi',c:hasF,title:()=>'Kapıdaki usta',text:()=>'Eski bir şantiyeden tanıdık bir usta geldi: rakibinden ayrılmış, takımıyla iş arıyor.',o:(w)=>[pay(w,sc(w,.2),'Al, hoş geldin',(w)=>{const f=w.firm!;addCrew(w,3);f.qual=clamp(f.qual+5,0,100);return'Ekip büyüdü, işin kalitesi arttı.';}),ok('Şimdilik kadro yeterli',()=>'Rakibin de aynı teklifi duydu.')]});
def({id:'piyango_ihale',kind:'iyi',w:.8,c:(w)=>st(w,8),title:()=>'Ek iş teklifi',text:()=>'Kurumdaki tanıdık aradı: bir okul bahçesi, ufak bir ek iş; kimse istemedi, sen istersen senin.',o:(w)=>[ok('Olur, küçük kâr',(w)=>{cash(w,sc(w,.5));rep(w,1);return'Bir ayda bitti, hakedişi zamanında geldi.';})]});
// Rakip
def({id:'rakip_arsa',kind:'kotu',c:(w)=>hasF(w)&&w.offers.length>0,title:(w)=>w.rival.name+' arsayı kapıyor',text:(w)=>`${w.rival.head} ${w.rival.name}, göz koyduğun arsanın sahibine daha yüksek pay teklif etmiş. Arsa sahibi seni aradı: "Ne yapacağız?"`,o:(w)=>[
 pay(w,sc(w,.3),'Üstüne koy',()=>'Arsa sende. Kârın incelir.'),
 ok('Bırak gitsin',(w)=>{w.offers.pop();w.rival.rel-=4;return'Kartını sakladın.';}),
 ok('Hatırla arsa sahibini ikna et',(w)=>{if(w.hatir>=5){hatir(w,-5);w.rival.rel-=8;return'Babasını tanıyordun. Arsa sende kaldı, rakibin küplere bindi.';}w.offers.pop();return'Hatır yetmedi.';})]});
def({id:'rakip_iftira',kind:'kotu',c:(w)=>st(w,3)&&w.rival.rel<45,title:()=>'Mahallede bir söylenti',text:(w)=>`"${w.surname} binaları çürük" diye bir söz dolanıyor. Kaynağı belli: ${ek(w.rival.name,'gen')} satış ofisi.`,o:(w)=>[
 pay(w,sc(w,.3),'Karot aldır, sonucu ilan et',(w)=>{if(w.buildings.every(b=>b.struct>45)){rep(w,5);return'Sonuçlar iyi çıktı, karşı tarafın yüzü kızardı.';}rep(w,-8);return'Sonuçlar iyi çıkmadı. Bunu sen de biliyordun, değil mi?';}),
 ok('Sen de onlar için söylet',(w)=>{w.rival.rel-=10;rep(w,-1);w.guilt+=1;return'Kahvede herkes birbirinin çürüğünü konuşuyor artık.';}),
 ok('Sus, işine bak',(w)=>{rep(w,-2);return'Söz sönümlendi, yavaş.';})]});
def({id:'rakip_ortak',kind:'iyi',w:1.5,gap:120,c:(w)=>st(w,15),title:(w)=>w.rival.name+' ile masada',text:(w)=>`${w.rival.head} ${w.rival.name} kahve içmeye çağırdı. Büyük işlerde ortaklık öneriyor: maliyet yarıya, kâr yarıya, güven sıfıra.`,o:(w)=>[ok('Sıradaki büyük işte ortağım olsun',(w)=>{w.flags.ortak=1;w.rival.rel+=12;return'Bir sonraki projede maliyetin ve kârın daha az olacak.';}),ok('Bu şehirde iki kral olmaz',(w)=>{w.rival.rel-=8;return'Fincanı bıraktın. O da bıraktı.';})]});
def({id:'rakip_evlilik',kind:'iyi',w:1.5,gap:150,c:(w)=>w.rival.stage>3&&kids(w).some(k=>age(w,k)>=20&&age(w,k)<35&&k.sp===undefined),mk:(w)=>({k:kids(w).find(k=>age(w,k)>=20&&age(w,k)<35&&k.sp===undefined)!.id}),title:(w)=>w.rival.name+' ailesinden dünür',text:(w,a)=>`${w.people[a.k].name} ile ${w.rival.name}'lerin çocuğu birbirini sevmiş ya da birileri öyle uygun görmüş. İki aile kaç yıldır kavgalı, hepsi aynı düğünde mi oynayacak?`,o:(w,a)=>[
 ok('Düğün yapılsın, barış olsun',(w)=>{const k=w.people[a.k];const s=addPerson(w,{sex:k.sex==='e'?'k':'e',by:k.by+ri(w,-24,24),sur:w.rival.name,dream:'',gen:k.gen});s.sp=k.id;k.sp=s.id;w.rival.rel=75;bond(w,k.id,18);cash(w,-sc(w,.3));log(w,`${k.name}, ${w.rival.name} ailesiyle evlendi.`,'aile');return'Bir masada iki aile. Davulcu bile şaşırdı.';}),
 ok('Olmaz',(w)=>{bond(w,a.k,-25);w.rival.rel-=6;return'Çocuğun odasına çekildi. Yıllarca sana bunu hatırlatacak.';})]});
// Vicdan
def({id:'gece',kind:'not',w:2,gap:36,c:(w)=>w.guilt>=12,title:()=>'Gece üçte',text:(w)=>{const bb=w.buildings.filter(b=>b.q==='kis'&&b.state==='ayakta');return bb.length?`Tavanda bir çatırtı var sandın. Yok. Sonra ${bb[0].name} geldi aklına; ${bb[0].residents[0]||'kim oturuyor'} ... ${spouse(w)?spouse(w)!.name+' "Niye uyumuyorsun?" dedi.':'Ev sessiz.'}`:`Kolonların çatladığı bir rüyadan uyandın. ${spouse(w)?spouse(w)!.name+' "Yine mi?" dedi.':'Yanında kimse yok.'}`;},o:(w)=>[ok('Kalk, su iç',(w)=>{stress(w,8);hurt(w,1);}),pay(w,sc(w,.7),'Binayı gizlice güçlendirt',(w)=>{const b=w.buildings.find(b=>b.q==='kis'&&b.state==='ayakta');if(b){b.struct+=28;b.q='nor';}w.guilt=Math.max(0,w.guilt-7);return'Ekip "su tesisatı" diye girdi. Sakinler sebebini bilmiyor.';})]});
def({id:'sakin',kind:'not',w:1.4,gap:48,c:(w)=>LIVE_BLD(w).some(b=>b.residents.length>0),mk:(w)=>{const b=pick(w,LIVE_BLD(w).filter(b=>b.residents.length>0));return{b:b.name,r:pick(w,b.residents)};},title:(w,a)=>a.b+' önünden geçerken',text:(w,a)=>{const l=[`${a.r} balkondan el salladı. Çocuğu büyümüş, "bu binayı sen yaptın" diye gösteriyor.`,`${a.r} ile bakkalda karşılaştın. "Depremde tık etmedi, Allah razı olsun" dedi.`,`${a.r} düğün davetiyesi gönderdi. Binanın bahçesinde olacakmış.`];return l[ri(w,0,2)];},o:(w,a)=>[ok('Selam verip geç',(w)=>{hatir(w,1);}),ok('Bir çayını iç',(w)=>{stress(w,-4);hatir(w,2);return'Duvara baktın, tuttuğun yerde çatlak yok.';})]});
def({id:'kalfa_santaj',kind:'kotu',w:1.2,gap:120,c:(w)=>hasF(w)&&w.buildings.some(b=>b.q==='kis'),title:()=>'Eski kalfa kapıda',text:()=>'Yıllar önce şantiyende çalışan kalfa, oturup bir sigara yaktı: "O kolonlara ne döktüğümüzü ikimiz biliyoruz. Çocuk hasta, para lazım."',o:(w)=>[
 pay(w,sc(w,.5),'Ver, gitsin',(w)=>{w.guilt+=2;later(w,ri(w,30,60),'kalfa_santaj');return'Gitti. Dönecek.';}),
 ok('Yok, ne yaparsan yap',(w)=>{if(chance(w,.5)){rep(w,-12);later(w,0,'davasi');return'Gazeteye gitti. Telefonlar kesildi.';}return'Blöf yapmış. Bir daha gelmedi.';}),
 pay(w,sc(w,1),'Beraber gidip binayı güçlendirelim',(w)=>{for(const b of w.buildings.filter(b=>b.q==='kis').slice(0,2)){b.struct+=25;b.q='nor';}w.guilt=Math.max(0,w.guilt-10);return'Kalfa hiç para almadı, sadece yanında çalıştı. Bazı şantajlar böyle biter.';})]});
def({id:'pencere',kind:'not',glass:true,c:()=>false,title:(w)=>'Pencereden '+year(w),text:(w)=>{const y=year(w);const era=y<1995?'Tarlalar yavaş yavaş gecekonduya, gecekondular üç katlıya dönüyor.':y<2010?'Apartmanlar omuz omuza. Vinç sayacak olsan akşam olur.':y<2030?'Kuleler dağın önüne geçti. Eski sokağını artık kuşbakışı bile bulamazsın.':'Şehir seni tanımıyor artık. Ama adın hâlâ birkaç tabelada duruyor.';return `Beş yılda bir böyle durup bakarsın. ${era}`;},o:()=>[ok('Devam')]});
def({id:'kendi_santiye',kind:'not',w:1,gap:180,c:(w)=>st(w,12)&&hasP(w),title:()=>'Kendi şantiyende bir gün',text:(w)=>`${act(w)[0].name} şantiyesine haber vermeden, eski bir tulumla gittin. Kimse tanımadı. Bir kalfa eline kova tutuşturdu. Çırağın yevmiyesi iki aydır gelmemiş, iskele bağları eksikti.`,o:(w)=>[
 pay(w,sc(w,.4),'Akşam baret çıkar, iskeleyi ve yevmiyeyi düzelt',(w)=>{w.firm!.qual=clamp(w.firm!.qual+8,0,100);w.guilt=Math.max(0,w.guilt-4);return'Ertesi gün taşeronun yüzü bembeyazdı.';}),
 ok('Sessizce çık, müdürü ara',(w)=>{w.firm!.qual=clamp(w.firm!.qual+2,0,100);return'Sorun şimdilik kapandı. Omzun aynı yerden ağrıyor.';})]});
// ------------- HİKÂYE YAYLARI -------------
export const ARC:Record<string,string>={gecekondu:'gecekondu1',isim:'isim1',mala:'mala1',cemal:'cemal1',kardes:'kardes1',tapu:'tapu1',ortak:'ortak1',cirak:'cirak1',donus:'donus1',muhtar:'muhtar1',gazeteci:'gazeteci1',kiz:'kiz1'};
def({id:'gecekondu1',title:()=>'Bir gecede',text:()=>'Koğuşta söz dönüyor: "Hazine arazisine bu gece çatı atan, sabah zabıta gelse de yıkamaz." Sekiz komşu sözleşti. Duvar sabaha kadar bitecek. Ne dersin?',o:(w)=>[
 pay(w,Math.min(2500,6000),'Ben de varım, bir gecede evimi kuracağım',(w)=>{const r=ri(w,0,99);if(w.home<2&&r>=25){w.home=2;w.skills.duvar+=8;hatir(w,8);log(w,'Bir gecede gecekondu kurdun.','iyi');later(w,ri(w,48,120),'gecekondu2');return'Şafakta bacadan duman çıktı. Zabıta geldi, baktı, çay içti. Evin artık var.';}w.skills.duvar+=4;hatir(w,4);return'Şafağa yetişemedin, kepçe geldi, duvar yıkıldı. Komşular harcını ödedi. Bir daha denersin.';}),
 ok('Çok riskli',(w)=>{return'O gece uyudun. Sabah sekiz yeni ev vardı, hiçbiri senin değil.';})]});
def({id:'gecekondu2',kind:'iyi',title:()=>'İmar affı',text:()=>'Oy zamanı. Gecekonduna tapu geliyor. Müteahhit çoktan kapıda: "Bize ver, üç daire vereyim." Komşular da senden soruyor, sen işi bilirsin artık.',o:(w)=>[ok('Tapuyu al, sat',(w)=>{cash(w,sc(w,1.2));return'İlk defa tapulu bir şey sattın.';}),ok('Üstüne kat çık, kendin yap',(w)=>{w.skills.kalip+=5;hatir(w,6);return'Zemin bu yükü taşır mı? Taşır gibi görünüyor.';})]});
def({id:'isim1',title:()=>'Taze beton',text:()=>'Kolon dibinin betonu daha yaş. Kimse bakmıyor. Çivinin ucuyla adını yazsan, kırk yıl kimse görmez.',o:(w)=>[ok('Yaz',(w)=>{w.flags.isim=year(w);later(w,12*ri(w,30,40),'isim2');return`"${pl(w).name} ${year(w)}". Mala ile üstünü hafifçe düzelttin.`;}),ok('Boş ver',()=>'Beton kurudu. Kimsenin adı yazılmadı.')]});
def({id:'isim2',kind:'not',title:()=>'Enkazda bir yazı',text:(w)=>`Eski bir binanın yıkımını izliyorsun. Kepçe durdu, operatör seni çağırdı. Bir kolon parçasında çiviyle yazılmış: "${w.people[w.founderId].name} ${w.flags.isim}".`,o:(w)=>[ok('Kolon parçasını ofise getir',(w)=>{w.guilt=Math.max(0,w.guilt-5);w.flags.isimtas=1;log(w,'Eski kolonu ofise getirdin.','aile');return'Ustalar geçerken o parçaya dokunuyor.';}),ok('Yıkım devam etsin',()=>'Toz kalktı, geçti.')]});
def({id:'mala1',kind:'iyi',title:()=>'Rıza Usta',text:()=>'Yaşı yetmişe yakın Rıza Usta seni süzdü: "Sen kolonu dinliyorsun evlat. Akşamları gel, sana öğreteceğim. Karşılığında yalnız yalan söyleme."',o:()=>[ok('Akşamlar onun',(w)=>{for(const k in w.skills)w.skills[k]+=5;w.flags.rizaOk=1;later(w,ri(w,30,70),'mala2');return'Yoruldun ama elin başka tutuyor artık.';}),ok('Vaktim yok',(w)=>{w.flags.rizaOk=0;return'Başını salladı, yoluna gitti.';})]});
def({id:'mala2',kind:'not',title:()=>'Rıza Usta\'nın malası',text:()=>'Hastane odasında elini tuttu. Yastığın altından aşınmış bir mala çıkardı: "Bunu çırağa ver derlerdi. Sen de bir gün vereceksin. Kime vereceğin, ne yaptığını gösterecek."',o:()=>[ok('Malayı al',(w)=>{w.flags.mala=1;for(const k in w.skills)w.skills[k]+=3;log(w,'Rıza Usta öldü, malası sana kaldı.','aile');return'Cenazede en önde sen vardın.';})]});
def({id:'cemal1',title:()=>'Koğuş arkadaşı Cemal',text:()=>'Cemal yatağın yanına oturdu: "Kardeşim, köyde babam hasta. Sana yemin ederim üç aya öderim."',o:(w)=>[pay(w,Math.round(Math.max(100,w.cash*.5)),'Ver',(w)=>{w.flags.cemal=1;later(w,ri(w,60,120),'cemal2');return'Sabah gitmişti. Bir not bırakmış: "Unutmam."';}),ok('Yok ki vereyim',(w)=>{w.flags.cemal=-1;later(w,ri(w,60,120),'cemal2');return'Başını öne eğdi. Bir daha aynı masada oturmadı.';})]});
def({id:'cemal2',title:()=>'Cemal geri döndü',text:(w)=>w.flags.cemal>0?'Takım elbiseli biri ofise girdi. Cemal. Kendi taşeron firması varmış. "Sana borcum vardı," dedi ve zarfı koydu. Yanında bir de teklif: "Kaba inşaatı bana ver, göz açtırmam."':'Cemal şimdi belediyede iş takipçisi. Ruhsat işinde karşına çıktı. Hatırladı, sen de hatırladın. Masadan bakıyor.',o:(w)=>w.flags.cemal>0?[ok('Ekibine güven',(w)=>{const v=w.firm?sc(w,.6):1500;cash(w,v);if(w.firm)w.firm.qual=clamp(w.firm.qual+6,0,100);later(w,ri(w,48,96),'cemal3');return'Zarf da, iş de iyi. Dostluk yeniden kuruldu.';}),ok('Parayı al, işi verme',(w)=>{cash(w,1000);return'Kırılmadı gibi yaptı.';})]:[pay(w,sc(w,.3),'Eski günleri söyle, gönlünü al',(w)=>{hatir(w,4);return'Ruhsat çıktı. Yüzü gülmedi.';}),ok('Yüzüne bak, başka kapıya git',(w)=>{if(w.projects[0])w.projects[0].seal+=2;return'İki ay fazladan koşturdun.';})]});
def({id:'cemal3',kind:'kotu',title:()=>'Cemal\'in son işi',text:()=>'Cemal\'in firması batıyor. Sana kaba inşaatta düşük beton sattığı ortaya çıktı. Telefonda ağlıyor: "Elim mecbur kaldı, ailem..."',o:(w)=>[pay(w,sc(w,.8),'Binaları kontrol ettir, Cemal\'e iş ver',(w)=>{w.guilt=Math.max(0,w.guilt-3);hatir(w,8);return'Yeniden kolonlara baktınız. Eskisi gibi olmadı, ama olmadı değil.';}),ok('Dava aç, adını bitir',(w)=>{cash(w,sc(w,.4));w.guilt+=2;hatir(w,-6);return'Kazandın. Cenazesini gazeteden öğrendin.';})]});
def({id:'kardes1',title:()=>'Gurbete giden',text:(w)=>{const s=family(w).find(p=>p.gen===pl(w).gen&&p.id!==pl(w).sp);return `${s?s.name:'Küçük kardeşin'} "Almanya'ya işçi alıyorlar" diye eline bir kâğıt tutuşturdu. Bilet parası lazım.`;},o:(w)=>[pay(w,Math.round(Math.max(150,w.cash*.3)),'Gitsin, yol parasını veririm',(w)=>{w.flags.kardesGur=1;later(w,ri(w,96,180),'kardes2');return'Otogarda el salladı. Yıllarca mektubu kartpostala dönüştü.';}),ok('Gitmesin, yanımda çalışsın',(w)=>{w.flags.kardesGur=0;return'Kaldı. Sana hep "şantiye yerine Almanya olabilirdi" gözüyle baktı.';})]});
def({id:'kardes2',kind:'iyi',title:()=>'Mark ile dönen',text:()=>'Kardeşin dönmüş. Sırtında takım elbise, yanında Alman arabası. Birikimini yatırmak istiyor. "Ağabey sen işi bilirsin," diyor.',o:(w)=>[ok('Ortak olalım',(w)=>{cash(w,w.firm?sc(w,1.2):4000);later(w,ri(w,40,90),'kardes3');return'Kasa doldu, masada bir ortak daha var.';}),ok('Kendi parası kendine kalsın',()=>'Saygı duydu. Ama sonra başka müteahhide gitti.')]});
def({id:'kardes3',kind:'kotu',title:()=>'Kardeş payını istiyor',text:()=>'Kârı bölerken ses yükseldi. "Almanya\'da on sekiz yıl fabrikada ben çalıştım. Bu binaların yarısı benim." Haksız mı?',o:(w)=>[pay(w,sc(w,.8),'Payını ver, kardeş kalın',()=>'Bayramda yine aynı sofradasınız.'),ok('Hesap açık, yazılı bir şey yok',(w)=>{rep(w,-3);for(const p of family(w))if(p.gen===pl(w).gen)bond(w,p.id,-30);return'Kardeşler küstü. Anan arada kaldı.';})]});
def({id:'tapu1',kind:'kotu',title:()=>'Sahte tapu',text:()=>'Yeni arsayı aldıktan iki ay sonra yaşlı bir kadın geldi: "Bu arsa benim babamın, tapu sahte, kimden aldın?" Kâğıtları gösterdi, kâğıtları gerçek gibi.',o:(w)=>[pay(w,sc(w,1),'Kadına bedelini öde, temiz kapat',(w)=>{rep(w,3);return'Kadın dua etti. Satanın izini de sürdürdün, yurt dışına kaçmış.';}),ok('Avukat çıkar, tapum var',(w)=>{w.guilt+=4;if(chance(w,.5))return'Kadın davadan düştü, bir gün de gelmedi.';cash(w,-sc(w,1.4));rep(w,-6);if(w.projects[0])w.projects[0].seal+=5;return'Mahkeme kadını haklı buldu. Şantiye durdu.';})]});
def({id:'ortak1',title:()=>'Sessiz ortak',text:()=>'Siyah bir araba durdu. İyi giyimli adam: "Nakit sıkıntın varmış. Ben parayı koyarım, kârın üçte biri bana. Adım hiçbir yere yazılmayacak." Parası nereden, sormadı kimse.',o:(w)=>[ok('Al',(w)=>{cash(w,sc(w,2));w.flags.sessiz=1;w.guilt+=2;later(w,ri(w,36,84),'ortak2');return'Kasa bir anda doldu. Adam bir de kartvizit bırakmadı.';}),ok('Hayır',()=>'Araba ağır ağır gitti. Numaran onda artık.')]});
def({id:'ortak2',kind:'kotu',title:()=>'Sessiz ortak konuştu',text:()=>'Aynı araba yine kapıda. "Yeğenimi muhasebeye al, faturaların bir kısmını da bizim şirketten kes." Bu kez soru sormuyor.',o:(w)=>[ok('Dediğini yap',(w)=>{w.guilt+=7;w.flags.rusvetDos=1;cash(w,sc(w,.8));return'Bir kâğıda imza attın. O imza bir yerde duruyor.';}),pay(w,sc(w,3),'Parasını iki katıyla geri ver, çık',(w)=>{w.flags.sessiz=0;stress(w,10);return'Kutuyu masaya koydun. Yüzünde hiç ifade yoktu. Bir süre arka kapıdan girip çıkacaksın.';}),ok('Savcıya git',(w)=>{w.flags.sessiz=0;rep(w,4);if(chance(w,.4)){hurt(w,12);cash(w,-sc(w,.8));return'Şantiye gece kundaklandı, sen de yaralandın. Ama dosya açıldı.';}return'Adam tutuklandı. Bir süre kapını kilitledin.';})]});
def({id:'cirak1',kind:'iyi',title:()=>'Kapıdaki çırak',text:()=>'On altı yaşında bir köylü oğlan kapıda, ayakkabısı delik. "Usta, ne iş olsa yaparım." Bir an aynaya bakar gibi oldun.',o:(w)=>[ok('Al, kendin yetiştir',(w)=>{w.flags.cirak=pick(w,MNAMES);later(w,ri(w,48,96),'cirak2');return`${w.flags.cirak} ilk gün tuğla taşıdı. İkinci gün iş sordu.`;}),ok('Ustabaşına yönlendir',()=>'Gitti. Bir daha sormadın adını.')]});
def({id:'cirak2',kind:'iyi',title:(w)=>w.flags.cirak+' büyüdü',text:(w)=>`${w.flags.cirak} artık en iyi ustan. Rakibin ona iki katını teklif etmiş. Sana söylemeye geldi; yani gitmek istemiyor, ama teklif gerçek.`,o:(w)=>[pay(w,sc(w,.4),'Ortak gibi tut',(w)=>{if(w.firm){w.firm.qual=clamp(w.firm.qual+10,0,100);w.firm.engs.push({id:w.nid++,name:w.flags.cirak,sk:80,hon:90,pid:-1});}return'Şantiyelerde artık sen gitmeden işler kontrol ediliyor.';}),ok('Gitsin, herkes kendi yolunda',(w)=>{w.rival.stage+=1;return'Rakibinin betonu iyileşti, seninki aynı kaldı.';}),ok('Malayı ona ver',(w)=>{w.flags.malaCirak=1;if(w.firm)w.firm.qual=clamp(w.firm.qual+12,0,100);hatir(w,10);w.guilt=Math.max(0,w.guilt-4);return'Gözleri doldu. Sen de usta olduğunu o gün anladın.';})]});
def({id:'donus1',title:()=>'On iki malik',text:()=>'Çürük bir apartmanın sakinleri seni çağırdı. Dönüşüm istiyorlar, ama üç kişi imza atmıyor: biri balkonuna, biri emekli maaşına, biri rahmetli kocasının ağacına bağlı.',o:(w)=>[pay(w,sc(w,.3),'Tek tek evlerine git, razı et',(w)=>{hatir(w,12);rep(w,4);return'Üç ay çay içtin, bir ağacı yeni bahçeye taşıdın. Herkes imzaladı.';}),ok('Çoğunluk yasası, zorla',(w)=>{w.guilt+=3;rep(w,-5);cash(w,sc(w,.5));return'Hukuken haklıydın. O kadın bir daha sokağa çıkmadı.';})]});
def({id:'muhtar1',title:()=>'Muhtarlık seçimi',text:()=>'Mahalle sana bakıyor: "Sen muhtar ol ya da bizim adayın arkasında dur." Hatır defterinin en kalın sayfası burada yazılır.',o:(w)=>[pay(w,sc(w,.2),'Adayı destekle',(w)=>{hatir(w,14);return'Kazandı. Şimdi sana borçlu. Sonra sen ona.';}),ok('Siyasete bulaşmam',()=>'Hem bu hem öbür taraf seni kendinden saymıyor.')]});
def({id:'gazeteci1',kind:'kotu',c:hasF,title:()=>'Genç gazeteci',text:(w)=>`Bir muhabir, ${w.surname} binalarını araştırıyormuş. Sorularını yolladı. Yanıtsız kalırsa yayımlayacakmış. O gazetede reklamın da var.`,o:(w)=>[ok('Şantiyeyi aç, sorularını yanıtla',(w)=>{if(w.guilt<10){rep(w,6);return'Sağlam bir yazı çıktı, satış ofisine kuyruk girdi.';}rep(w,-10);return'Bulduğu şeyi yazdı.';}),pay(w,sc(w,.3),'Gazete sahibini ara',(w)=>{w.guilt+=2;return'Haber çıkmadı. Muhabir başka şehre gitti, klasör de onunla.';})]});
def({id:'kiz1',kind:'iyi',title:()=>'Şantiyedeki kadın',text:()=>'Şantiyeye genç bir kadın inşaat mühendisi atandı. Ustalar kıs kıs gülüyor. İki gün sonra, kimsenin görmediği bir hatayı buldu.',o:(w)=>[ok('Arkasında dur, yetki ver',(w)=>{if(w.firm){w.firm.engs.push({id:w.nid++,name:pick(w,FNAMES)+' Hanım',sk:78,hon:85,pid:-1});w.firm.qual=clamp(w.firm.qual+8,0,100);}return'Takım iki hafta homurdandı, sonra alıştı. Kolonlar da teşekkür etti.';}),ok('"Şantiye sana göre değil" de',(w)=>{rep(w,-2);return'Rakibinin baş mühendisi oldu sonra.';})]});
// Devir sonrası
def({id:'dosya',kind:'not',title:()=>'Kasadaki dosya',text:(w)=>`${w.flags.dosyaDede||'Önceki patron'} giderken kasaya bir dosya bırakmış. İçinde bir bina listesi, kimi isimlerin yanında çarpı var: nerede demir kısılmış, kime zarf verilmiş.`,o:(w)=>[
 pay(w,sc(w,1.2),'Listedeki binaları sessizce güçlendir',(w)=>{for(const b of w.buildings.filter(b=>b.q==='kis')){b.struct+=26;b.q='nor';}w.guilt=0;return'Dedenin adı kurtuldu, kasan boşaldı.';}),
 ok('Yak',(w)=>{w.guilt+=4;return'Soba içinde kâğıt çabuk yandı. Binalar yerinde duruyor, sakinleri içinde.';}),
 ok('Kamuoyuna itiraf et',(w)=>{rep(w,-20);w.guilt=0;for(const b of w.buildings.filter(b=>b.q==='kis'))b.state='donusum';return'Şirket sarsıldı. Sakinler ilk kez sana inandı.';})]});
def({id:'efsane',kind:'not',c:(w)=>!!w.legacy,gap:9999,title:()=>'Eski bir tabela',text:(w)=>`Sokakta yıpranmış bir tabela gördün: "${w.legacy} ve Oğulları". Şehirde hikâyesi anlatılan bir aile. Binalarından birinin önündesin.`,o:()=>[ok('Bir süre bak',(w)=>{w.skills.beton+=1;return'Kolonları hâlâ dimdik. Bir gün senin adını da böyle okurlar mı?';})]});
// Köşe olayları
def({id:'piyasa_patlama',kind:'iyi',c:(w)=>w.econ.phase==='patlama'&&hasF(w),title:()=>'Herkes daire arıyor',text:()=>'Faiz düştü, satış ofisi kuyruğa döndü. Bu hafta üç arsa sahibi kapını çaldı. Ama herkes dikmeye başlarsa kim alacak?',o:(w)=>[ok('Bol keseden proje aç',(w)=>{for(let i=0;i<2;i++)w.flags.bonusOffer=(w.flags.bonusOffer||0)+1;return'Teklif defteri doldu.';}),ok('Temkinli devam',(w)=>{rep(w,1);return'Üç yıl sonra bu kararı hatırlarsın.';})]});
def({id:'es_olum',kind:'kotu',w:.8,gap:120,c:(w)=>!!spouse(w)&&age(w,spouse(w)!)>60,title:(w)=>spouse(w)!.name,text:(w)=>`${ek(spouse(w)!.name,'gen')} doktoru seni koridora aldı. Yüzünde o bilindik ifade var.`,o:(w)=>[pay(w,sc(w,.3),'Son aylarını yanında geçir',(w)=>{const s=spouse(w)!;s.dm=w.m;s.cause='hastalık';w.stats.dead++;log(w,`${s.name} öldü.`,'aile');stress(w,18);return'Sabahları kahveyi iki fincan koymaya devam ettin.';}),ok('İşe sarıl',(w)=>{const s=spouse(w)!;s.dm=w.m;s.cause='hastalık';w.stats.dead++;log(w,`${s.name} öldü.`,'aile');stress(w,28);w.guilt+=3;return'Cenazeden çıkıp şantiyeye gittin. Kimse bir şey demedi.';})]});
def({id:'saglik',kind:'kotu',c:(w)=>age(w,pl(w))>45&&w.stress>55,title:()=>'Kalp doktoru',text:()=>'"Bu tempo böyle sürmez," dedi doktor, kâğıdı önüne koyarken.',o:(w)=>[pay(w,sc(w,.3),'Dinle, işleri devret, kür yap',(w)=>{w.health=clamp(w.health+18,1,100);stress(w,-30);return'Şantiyeden iki ay uzak kaldın. Kimse ölmedi.';}),ok('Doktorlar hep öyle der',(w)=>{hurt(w,12);return'Merdivenleri bu kez durarak çıktın.';})]});

// ------------- DEPO, USTA, MÜŞTERİ -------------
def({id:'depo_hirsiz',kind:'kotu',c:(w)=>hasF(w)&&(w.stock.demir||0)>2,title:()=>'Geceleyin demir gitmiş',text:()=>'Sabah depo kapısı açık, demir yığını eksik. Bekçi "uyumuşum" diyor, gözleri başka yere bakıyor.',o:()=>[pay0('Bekçiyi çıkar, kamera gibi ikinci bekçi tut',.15,(w)=>{w.stock.demir*=.7;return'Bir daha böyle gece olmadı. Yevmiyeler arttı.';}),ok('Zararı yaz, devam et',(w)=>{w.stock.demir*=.6;stress(w,4);return'Hırsız bir daha gelir diye herkes birbirine bakıyor.';})]});
def({id:'cimento_yagmur',kind:'kotu',c:(w)=>hasF(w)&&(w.stock.cimento||0)>3,title:()=>'Çimentolar ıslandı',text:()=>'Gece bastıran yağmur brandayı açmış. Torbalar taş gibi. Kalfa "biraz kırıp kullanırız" diyor.',o:()=>[ok('Hepsini at',(w)=>{w.stock.cimento*=.65;return'Pahalı ders. Beton sağlam kaldı.';}),ok('Kırıp kullanın',(w)=>{w.stock.cimento*=.95;w.guilt+=3;const p=act(w)[0];if(p)p.struct-=6;return'Mikser homurdandı. Yazmadın bunu deftere.';})]});
def({id:'usta_zam',kind:'kotu',c:(w)=>hasF(w)&&Object.values(w.firm!.crews).some(c=>c.n>=3),mk:(w)=>({t:Object.keys(w.firm!.crews).filter(k=>w.firm!.crews[k].n>=3)[0]}),title:(w,a)=>w.firm!.crews[a.t].usta+' Usta zam istiyor',text:(w,a)=>`${w.firm!.crews[a.t].usta} Usta başını kaldırdı: "Rakip %20 fazla veriyor. Ekibim seni seviyor ama çocukları da var."`,o:(w,a)=>[pay0('Primle karşıla, kalsınlar',.15,(w)=>{w.firm!.crews[a.t].sk=clamp(w.firm!.crews[a.t].sk+4,0,100);return'Ekip kaldı, iş hızlandı.';}),ok('Veremem',(w)=>{const c=w.firm!.crews[a.t];c.n=Math.ceil(c.n*.6);return'Yarısı sabah gelmedi. Yerlerine yenisini bulman lazım.';})]});
def({id:'musteri',kind:'iyi',c:(w)=>w.projects.some(p=>p.units.some(u=>!u.own&&u.sold<u.n)&&p.sellOn),mk:(w)=>{const p=pick(w,w.projects.filter(p=>p.units.some(u=>!u.own&&u.sold<u.n)));return{p:p.id,who:pick(w,['Emekli öğretmen','Gurbetçi işçi','Genç doktor','Esnaf','Yeni evli çift'])+' '+pick(w,MNAMES)};},title:(w,a)=>a.who+' daire bakıyor',text:(w,a)=>{const p=w.projects.find(x=>x.id===a.p);return`${a.who}, ${p?p.name:'projeni'} gezdi, balkondan aşağı baktı. "Beğendim," dedi, "ama bu fiyata peşin alamam."`;},o:(w,a)=>[ok('Peşin %6 indir',(w)=>{const p=w.projects.find(x=>x.id===a.p);if(p){const v=sellNow(w,p,.01,.94);return money(v)+' kasaya girdi. Mutlu ayrıldı.';}}),ok('Senetle ver, tam fiyat',(w)=>{const p=w.projects.find(x=>x.id===a.p);if(p){const v=sellNow(w,p,.01,1.02);w.cash-=v;for(let i=1;i<=10;i++)w.payables.push({m:w.m+i*2,amt:-v/10,note:'Senet: '+a.who});return'On senet imzaladı. Hepsi ödenir mi, göreceğiz.';}}),ok('Fiyatta oynamam',()=>'Gitti. Belki döner, belki dönmez.')]});
def({id:'kis_beton',kind:'kotu',c:(w)=>hasP(w)&&(mon(w)===11||mon(w)<2)&&act(w).some(p=>['beton','temel'].includes(p.items[p.cur]?.id)),title:()=>'Don var, beton sırada',text:()=>'Termometre eksi beşi gösteriyor. Mikser saati alınmış. Don yiyen beton dışı sağlam, içi çürük olur.',o:(w)=>[pay0('Isıtıcı ve antifriz getir',.1,()=>'Pahalı oldu, gece nöbet tutuldu.'),ok('Dök gitsin',(w)=>{const p=act(w)[0];p.struct-=8;w.guilt+=3;return'Sabah yüzey iyi görünüyordu.';}),ok('Baharı bekle',(w)=>{seal(w,{},2);return'Şantiye sustu, kira sürdü.';})]});
def({id:'muh_hirsiz',kind:'kotu',c:(w)=>hasF(w)&&w.firm!.engs.some(e=>e.hon<50&&e.pid>0),mk:(w)=>({e:w.firm!.engs.find(e=>e.hon<50&&e.pid>0)!.id}),title:()=>'Mühendisin hesabı',text:(w,a)=>`${w.firm!.engs.find(e=>e.id===a.e)?.name} şantiyede faturalar şişmiş. Muhasebeci ikiye iki koyunca fark ettin.`,o:(w,a)=>[ok('Kovdur, savcıya ver',(w)=>{w.firm!.engs=w.firm!.engs.filter(e=>e.id!==a.e);cash(w,-sc(w,.2));return'Şantiye sahipsiz kaldı. Yeni mühendis bul.';}),ok('Uyar, sessiz kal',(w)=>{const e=w.firm!.engs.find(e=>e.id===a.e);if(e)e.hon+=12;cash(w,-sc(w,.4));return'Söz verdi. İnandın mı? Pek değil.';})]});
export const MONTH_KINDS=['kotu','iyi','not'];
export function buildOpts(w:World,c:{id:string;a:any}):Opt[]{return EV[c.id].o(w,c.a);}
void rnd;void alive;void full;void TRADES;void mon;void clamp;void MATS;void soldFrac;
